mapper.delete:
DELETE FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

SELECT FROM meal_item m LEFT JOIN meal_knowledge k ON k.meal_id = m.id
m.source_type = 'PERSONAL' AND m.owner_user_id = #{userId}
m.source_type = 'PUBLIC' AND m.owner_user_id IS NULL
AND (#{mealTimeJson} = '[]' OR JSON_OVERLAPS(m.meal_time, #{mealTimeJson})) AND (#{moodJson} = '[]' OR JSON_OVERLAPS(m.mood, #{moodJson})) AND (#{sceneJson} = '[]' OR JSON_OVERLAPS(m.scene, #{sceneJson})) AND (#{healthGoalJson} = '[]' OR JSON_OVERLAPS(m.health_goal, #{healthGoalJson})) AND (#{cuisineJson} = '[]' OR JSON_OVERLAPS(m.cuisine, #{cuisineJson})) AND (#{tasteJson} = '[]' OR JSON_OVERLAPS(m.taste, #{tasteJson})) AND (#{convenienceJson} = '[]' OR JSON_OVERLAPS(m.convenience, #{convenienceJson})) AND ((#{requiredIngredientsJson} = '[]' AND #{excludedIngredientsJson} = '[]') OR (k.ingredients IS NOT NULL AND JSON_LENGTH(k.ingredients) > 0)) AND (#{requiredIngredientsJson} = '[]' OR JSON_CONTAINS(k.ingredients, #{requiredIngredientsJson})) AND (#{excludedIngredientsJson} = '[]' OR NOT JSON_OVERLAPS(k.ingredients, #{excludedIngredientsJson}))
ORDER BY m.updated_at DESC LIMIT #{limit}
